import{_ as i,a as l,c as a,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写","description":"历史 MySQL 库表、索引、分片与 SQL 审核规则","frontmatter":{"title":"MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写","description":"历史 MySQL 库表、索引、分片与 SQL 审核规则","splitFrom":"middleware/mysql/plus/practice/mysql设计规范.md","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"},{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"应用实践","scope":"historical","audience":"general","group":"数据库与存储","seriesTitle":"MySQL数据库设计规范","summary":"历史 MySQL 库表、索引、分片与 SQL 审核规则","status":"active","related":[{"title":"MySQL数据库设计规范","link":"/middleware/mysql/plus/practice/mysql%E8%AE%BE%E8%AE%A1%E8%A7%84%E8%8C%83","kind":"应用实践","scope":"historical","audience":"general"},{"title":"MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范","link":"/middleware/mysql/plus/practice/mysql设计规范-part-01","kind":"应用实践","scope":"historical","audience":"general"},{"title":"朋友圈（广场设计）","link":"/principles/distributed-architecture/architecture/cases/%E6%9C%8B%E5%8F%8B%E5%9C%88(%E5%B9%BF%E5%9C%BA%E8%AE%BE%E8%AE%A1)","kind":"架构取舍与原文","scope":"historical","audience":"general"},{"title":"Redis：数据结构服务、缓存与部署边界","link":"/middleware/redis/foundations","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis：数据结构服务、缓存与部署边界 · 缓存异常至延伸阅读","link":"/middleware/redis/foundations-part-03","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范","link":"/middleware/mysql/plus/practice/mysql设计规范-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL数据库设计规范 · 1. 规范背景与目的至2. 设计规范","link":"/middleware/mysql/plus/practice/mysql设计规范-part-01"},"next":false},"headers":[],"relativePath":"middleware/mysql/plus/practice/mysql设计规范-part-02.md","filePath":"middleware/mysql/plus/practice/mysql设计规范-part-02.md"}'),o={name:"middleware/mysql/plus/practice/mysql设计规范-part-02.md"};function r(t,e,c,n,s,m){return l(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="mysql数据库设计规范-·-2-1-7-程序层dao设计建议至2-2-sql编写" tabindex="-1">MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写 <a class="header-anchor" href="#mysql数据库设计规范-·-2-1-7-程序层dao设计建议至2-2-sql编写" aria-label="Permalink to &quot;MySQL数据库设计规范 · 2.1.7 程序层DAO设计建议至2.2 SQL编写&quot;">​</a></h1><p><a href="/middleware/mysql/plus/practice/mysql设计规范">返回分篇目录</a></p><h2 id="_2-1-7-程序层dao设计建议" tabindex="-1">2.1.7 程序层DAO设计建议 <a class="header-anchor" href="#_2-1-7-程序层dao设计建议" aria-label="Permalink to &quot;2.1.7 程序层DAO设计建议 {#_2-1-7-程序层dao设计建议}&quot;">​</a></h2><ol><li>【建议】新的代码不要用model，推荐使用手动拼SQL+绑定变量传入参数的方式。因为model虽然可以使用面向对象的方式操作db，但是其使用不当很容易造成生成的SQL非常复杂，且model层自己做的强制类型转换性能较差，最终导致数据库性能下降。</li><li>【建议】前端程序连接MySQL或者redis，必须要有连接超时和失败重连机制，且失败重试必须有间隔时间。</li><li>【建议】前端程序报错里尽量能够提示MySQL或redis原生态的报错信息，便于排查错误。</li><li>【建议】对于有连接池的前端程序，必须根据业务需要配置初始、最小、最大连接数，超时时间以及连接回收机制，否则会耗尽数据库连接资源，造成线上事故。</li><li>【建议】对于log或history类型的表，随时间增长容易越来越大，因此上线前RD或者DBA必须建立表数据清理或归档方案。</li><li>【建议】在应用程序设计阶段，RD必须考虑并规避数据库中主从延迟对于业务的影响。尽量避免从库短时延迟（20秒以内）对业务造成影响，建议强制一致性的读开启事务走主库，或更新后过一段时间再去读从库。</li><li>【建议】多个并发业务逻辑访问同一块数据（innodb表）时，会在数据库端产生行锁甚至表锁导致并发下降，因此建议更新类SQL尽量基于主键去更新。</li><li>【建议】业务逻辑之间加锁顺序尽量保持一致，否则会导致死锁。</li><li>【建议】对于单表读写比大于10:1的数据行或单个列，可以将热点数据放在缓存里（如mecache或redis），加快访问速度，降低MySQL压力。</li></ol><h2 id="_2-1-8一个规范的建表语句示例" tabindex="-1">2.1.8 一个规范的建表语句示例 <a class="header-anchor" href="#_2-1-8一个规范的建表语句示例" aria-label="Permalink to &quot;2.1.8	一个规范的建表语句示例 {#_2-1-8一个规范的建表语句示例}&quot;">​</a></h2><p>一个较为规范的建表语句为：</p><pre><code>CREATE TABLE user (\n  `id` bigint(11) NOT NULL AUTO_INCREMENT,\n  `user_id` bigint(11) NOT NULL COMMENT &#39;用户id&#39;,\n  `username` varchar(45) NOT NULL COMMENT &#39;真实姓名&#39;,\n  `email` varchar(30) NOT NULL COMMENT &#39;用户邮箱&#39;,\n  `nickname` varchar(45) NOT NULL COMMENT &#39;昵称&#39;,\n  `avatar` int(11) NOT NULL COMMENT &#39;头像&#39;,\n  `birthday` date NOT NULL COMMENT &#39;生日&#39;,\n  `sex` tinyint(4) DEFAULT &#39;0&#39; COMMENT &#39;性别&#39;,\n  `short_introduce` varchar(150) DEFAULT NULL COMMENT &#39;一句话介绍自己，最多50个汉字&#39;,\n  `user_resume` varchar(300) NOT NULL COMMENT &#39;用户提交的简历存放地址&#39;,\n  `user_register_ip` int NOT NULL COMMENT &#39;用户注册时的源ip&#39;,\n  `create_time` timestamp NOT NULL COMMENT &#39;用户记录创建的时间&#39;,\n  `update_time` timestamp NOT NULL COMMENT &#39;用户资料修改的时间&#39;,\n  `user_review_status` tinyint NOT NULL COMMENT &#39;用户资料审核状态，1为通过，2为审核中，3为未通过，4为还未提交审核&#39;,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `idx_user_id` (`user_id`),\n  KEY `idx_username`(`username`),\n  KEY `idx_create_time`(`create_time`,`user_review_status`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT=&#39;网站用户基本信息&#39;;\n</code></pre><h2 id="_2-2-sql编写" tabindex="-1">2.2 SQL编写 <a class="header-anchor" href="#_2-2-sql编写" aria-label="Permalink to &quot;2.2 SQL编写 {#_2-2-sql编写}&quot;">​</a></h2><h3 id="_2-2-1-dml语句" tabindex="-1">2.2.1 DML语句 <a class="header-anchor" href="#_2-2-1-dml语句" aria-label="Permalink to &quot;2.2.1 DML语句 {#_2-2-1-dml语句}&quot;">​</a></h3><ol><li>【强制】SELECT语句必须指定具体字段名称，禁止写成<code>*</code>。因为<code>select *</code>会将不该读的数据也从MySQL里读出来，造成网卡压力。且表字段一旦更新，但model层没有来得及更新的话，系统会报错。</li><li>【强制】insert语句指定具体字段名称，不要写成<code>insert into t1 values(…)</code>，道理同上。</li><li>【建议】<code>insert into…values(XX),(XX),(XX)…</code>。这里XX的值不要超过5000个。值过多虽然上线很很快，但会引起主从同步延迟。</li><li>【建议】SELECT语句不要使用<code>UNION</code>，推荐使用<code>UNION ALL</code>，并且<code>UNION</code>子句个数限制在5个以内。因为<code>union all</code>不需要去重，节省数据库资源，提高性能。</li><li>【建议】in值列表限制在500以内。例如<code>select… where userid in(….500个以内…)</code>，这么做是为了减少底层扫描，减轻数据库压力从而加速查询。</li><li>【建议】事务里批量更新数据需要控制数量，进行必要的sleep，做到少量多次。</li><li>【强制】事务涉及的表必须全部是innodb表。否则一旦失败不会全部回滚，且易造成主从库同步终端。</li><li>【强制】写入和事务发往主库，只读SQL发往从库。</li><li>【强制】除静态表或小表（100行以内），DML语句必须有where条件，且使用索引查找。</li><li>【强制】生产环境禁止使用<code>hint</code>，如<code>sql_no_cache</code>，<code>force index</code>，<code>ignore key</code>，<code>straight join</code>等。因为<code>hint</code>是用来强制SQL按照某个执行计划来执行，但随着数据量变化我们无法保证自己当初的预判是正确的，因此我们要相信MySQL优化器！</li><li>【强制】where条件里等号左右字段类型必须一致，否则无法利用索引。</li><li>【建议】<code>SELECT|UPDATE|DELETE|REPLACE</code>要有WHERE子句，且WHERE子句的条件必需使用索引查找。</li><li>【强制】生产数据库中强烈不推荐大表上发生全表扫描，但对于100行以下的静态表可以全表扫描。查询数据量不要超过表行数的25%，否则不会利用索引。</li><li>【强制】WHERE 子句中禁止只使用全模糊的LIKE条件进行查找，必须有其他等值或范围查询条件，否则无法利用索引。</li><li>【建议】索引列不要使用函数或表达式，否则无法利用索引。如<code>where length(name)=&#39;Admin&#39;</code>或<code>where user_id+2=10023</code>。</li><li>【建议】减少使用or语句，可将or语句优化为union，然后在各个where条件上建立索引。如<code>where a=1 or b=2</code>优化为<code>where a=1… union …where b=2, key(a),key(b)</code>。</li><li>【建议】分页查询，当limit起点较高时，可先用过滤条件进行过滤。如<code>select a,b,c from t1 limit 10000,20;</code>优化为: <code>select a,b,c from t1 where id&gt;10000 limit 20;</code>。</li></ol><h3 id="_2-2-2-多表连接" tabindex="-1">2.2.2 多表连接 <a class="header-anchor" href="#_2-2-2-多表连接" aria-label="Permalink to &quot;2.2.2 多表连接 {#_2-2-2-多表连接}&quot;">​</a></h3><ol><li>【强制】禁止跨db的join语句。因为这样可以减少模块间耦合，为数据库拆分奠定坚实基础。</li><li>【强制】禁止在业务的更新类SQL语句中使用join，比如<code>update t1 join t2…</code>。</li><li>【建议】不建议使用子查询，建议将子查询SQL拆开结合程序多次查询，或使用join来代替子查询。</li><li>【建议】线上环境，多表join不要超过3个表。</li><li>【建议】多表连接查询推荐使用别名，且SELECT列表中要用别名引用字段，数据库.表格式，如<code>select a from db1.table1 alias1 where …</code>。</li><li>【建议】在多表join中，尽量选取结果集较小的表作为驱动表，来join其他表。</li></ol><h3 id="_2-2-3-事务" tabindex="-1">2.2.3 事务 <a class="header-anchor" href="#_2-2-3-事务" aria-label="Permalink to &quot;2.2.3 事务 {#_2-2-3-事务}&quot;">​</a></h3><ol><li>【建议】事务中<code>INSERT|UPDATE|DELETE|REPLACE</code>语句操作的行数控制在2000以内，以及WHERE子句中IN列表的传参个数控制在500以内。</li><li>【建议】批量操作数据时，需要控制事务处理间隔时间，进行必要的sleep，一般建议值5-10秒。</li><li>【建议】对于有<code>auto_increment</code>属性字段的表的插入操作，并发需要控制在200以内。</li><li>【强制】程序设计必须考虑“数据库事务隔离级别”带来的影响，包括脏读、不可重复读和幻读。线上建议事务隔离级别为<code>repeatable-read</code>。</li><li>【建议】事务里包含SQL不超过5个（支付业务除外）。因为过长的事务会导致锁数据较久，MySQL内部缓存、连接消耗过多等雪崩问题。</li><li>【建议】事务里更新语句尽量基于主键或<code>unique key</code>，如<code>update … where id=XX</code>; 否则会产生间隙锁，内部扩大锁定范围，导致系统性能下降，产生死锁。</li><li>【建议】尽量把一些典型外部调用移出事务，如调用webservice，访问文件存储等，从而避免事务过长。</li><li>【建议】对于MySQL主从延迟严格敏感的select语句，请开启事务强制访问主库。</li></ol><h3 id="_2-2-4-排序和分组" tabindex="-1">2.2.4 排序和分组 <a class="header-anchor" href="#_2-2-4-排序和分组" aria-label="Permalink to &quot;2.2.4 排序和分组 {#_2-2-4-排序和分组}&quot;">​</a></h3><ol><li>【建议】减少使用<code>order by</code>，和业务沟通能不排序就不排序，或将排序放到程序端去做。<code>order by</code>、<code>group by</code>、<code>distinct</code>这些语句较为耗费CPU，数据库的CPU资源是极其宝贵的。</li><li>【建议】<code>order by</code>、<code>group by</code>、<code>distinct</code>这些SQL尽量利用索引直接检索出排序好的数据。如<code>where a=1 order by</code>可以利用<code>key(a,b)</code>。</li><li>【建议】包含了<code>order by</code>、<code>group by</code>、<code>distinct</code>这些查询的语句，where条件过滤出来的结果集请保持在1000行以内，否则SQL会很慢。</li></ol><h3 id="_2-2-5-线上禁止使用的sql语句" tabindex="-1">2.2.5 线上禁止使用的SQL语句 <a class="header-anchor" href="#_2-2-5-线上禁止使用的sql语句" aria-label="Permalink to &quot;2.2.5 线上禁止使用的SQL语句 {#_2-2-5-线上禁止使用的sql语句}&quot;">​</a></h3><ol><li>【高危】禁用<code>update|delete t1 … where a=XX limit XX;</code> 这种带limit的更新语句。因为会导致主从不一致，导致数据错乱。建议加上<code>order by PK</code>。</li><li>【高危】禁止使用关联子查询，如<code>update t1 set … where name in(select name from user where…);</code>效率极其低下。</li><li>【强制】禁用procedure、function、trigger、views、event、外键约束。因为他们消耗数据库资源，降低数据库实例可扩展性。推荐都在程序端实现。</li><li>【强制】禁用<code>insert into …on duplicate key update…</code>在高并发环境下，会造成主从不一致。</li><li>【强制】禁止联表更新语句，如<code>update t1,t2 where t1.id=t2.id…</code>。</li></ol>',18)])])}const L=i(o,[["render",r]]);export{u as __pageData,L as default};
